// REGLA ① · sin manual de marca APROBADO no se sigue y no se escribe nada.
// Se detiene lanzando: n8n aborta y ningun nodo de abajo llega a correr.
const cid = $('Webhook · planeacion').first().json.body.client_id;
if (!cid) { throw new Error('PLANEACION_SIN_CLIENTE · falta client_id en el sobre'); }
// 🔴 EL MODO SECO (2026-09-30 · decisión de Emilio) · `dry_run` del sobre: AUSENTE ⇒ corre real como hoy (el despachador de la sala NO lo manda) ·
// booleano ⇒ se respeta · CUALQUIER OTRA COSA ("true", 1, null…) ⇒ la corrida SE DETIENE ANTES DE GASTAR: un valor que parece seco y no lo es
// pagaría al redactor creyendo que no (lección 28-sep: una prueba «gratis» cobró US$ 0,37).
const dryDelSobre = $('Webhook · planeacion').first().json.body.dry_run;
if (dryDelSobre !== undefined && typeof dryDelSobre !== 'boolean') {
  throw new Error('PLANEACION_DRY_RUN_INVALIDO · dry_run del sobre debe ser true o false (booleano) o no venir · llegó ' + JSON.stringify(dryDelSobre) + ' (' + typeof dryDelSobre + ') · se DETIENE antes de gastar: un valor que parece seco y no lo es pagaría al redactor');
}
const filas = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r.id; });
if (filas.length === 0) {
  throw new Error('PLANEACION_SIN_MANUAL · el cliente ' + cid + ' no tiene manual de marca · la corrida se detiene y NO escribe nada (regla 1)');
}
const m = filas[0];
// 'aprobado' = paso la vara. La marca del veredicto vive en gate_outcome.
const aprobado = m.gate_outcome === 'paso_la_vara';
if (!aprobado) {
  throw new Error('PLANEACION_MANUAL_NO_APROBADO · manual ' + m.id + ' con gate_outcome=' + JSON.stringify(m.gate_outcome) + ' · la corrida se detiene y NO escribe nada (regla 1)');
}
// REGISTRO DEL CLIENTE · CC#2 · relevo 62 · el redactor del plan toma el registro (tuteo / voseo / usted) del MANUAL del cliente y no lo inventa.
// Texto plano que se PEGA TAL CUAL dentro de los nodos «① GUARDA» y «Redactor (B4)» de la planeación; la prueba `__tests__/planeacion-registro-del-cliente.test.ts` ejecuta ESTE MISMO texto.
// Agnóstico: ningún cliente, ciudad ni rubro. Los países de abajo son un DATO (se amplía sin tocar la lógica).
// Orden de autoridad: 1) lo que el manual DECLARA · 2) lo que el manual ESCRIBE (≥ 2 marcas de un lado y 0 del otro) · 3) el país de la ficha, por omisión y DECLARADO como omisión · 4) sin dato (se dice).

// DATO · registro por omisión por país (claves en minúsculas y sin tildes). Un país que no está aquí NO tiene registro por omisión.
// ═══ PAÍS → TRATO · ÚNICA FUENTE (ronda 67 · CC#1 · 2026-10-11) ═══
// El trato habitual del país SÓLO cuando nadie lo dijo (baja confianza · se declara) · sin país conocido no hay default. UNA sola tabla: la planeación, el alta, el brief, la pieza y la copia por filas
// llevan ESTE MISMO bloque (lo pega el constructor y una prueba exige que sea idéntico). Las claves son el nombre en minúsculas y sin tildes; los códigos de dos letras y los alias entran por `paisNormal`.
// Es un DATO (se amplía sin tocar la lógica): la UNIÓN verificada de las tres tablas que se habían apartado (el detector: 12 países; el registro de la planeación: 15, con Colombia, Cuba, Puerto Rico y República Dominicana, sin Costa Rica).
var POR_PAIS = { argentina: 'vos', uruguay: 'vos', paraguay: 'vos', ecuador: 'tu', mexico: 'tu', peru: 'tu', chile: 'tu', espana: 'tu', bolivia: 'tu', venezuela: 'tu', panama: 'tu', colombia: 'tu', cuba: 'tu', 'puerto rico': 'tu', 'republica dominicana': 'tu', 'costa rica': 'usted' }
var CODIGO_PAIS = { ar: 'argentina', uy: 'uruguay', py: 'paraguay', ec: 'ecuador', mx: 'mexico', pe: 'peru', cl: 'chile', es: 'espana', bo: 'bolivia', ve: 'venezuela', pa: 'panama', co: 'colombia', cu: 'cuba', pr: 'puerto rico', do: 'republica dominicana', cr: 'costa rica' }
var ALIAS_PAIS = { dominicana: 'republica dominicana', 'rep dominicana': 'republica dominicana', spain: 'espana' }
/** el país como lo escribe una ficha («Ecuador.», «EC», «República Dominicana», «Rep. Dominicana») → la clave de la tabla; texto sin reconocer vuelve normalizado (nunca se adivina) */
function paisNormal(s) {
  var t = String(s === undefined || s === null ? '' : s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim()
  return CODIGO_PAIS[t] || ALIAS_PAIS[t] || t
}
// ═══ fin país → trato ═══
// el registro de la planeación se DERIVA de la única tabla (tu → tuteo · vos → voseo · usted → formal): no hay segunda lista de países
const REGISTRO_POR_PAIS = (() => { const r = {}; const m = { tu: 'tuteo', vos: 'voseo', usted: 'formal' }; Object.keys(POR_PAIS).forEach((k) => { r[k] = m[POR_PAIS[k]] }); return r })()
const _sinTildes = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim()
// «palabra completa» con letras Unicode (\b no sirve con tildes)
const _pal = (alt) => new RegExp('(?<![\\p{L}\\p{N}])(?:' + alt + ')(?![\\p{L}\\p{N}])', 'giu')
const _VOSEO = _pal('vos|tenés|querés|podés|hacés|sabés|decís|venís|vivís|sos|pedí|vení|probá|mirá|elegí|escribí|descubrí|seguí|animate|sumate|fijate|acordate|andá|salí')
const _TUTEO = _pal('tú|tienes|quieres|puedes|haces|sabes|dices|vienes|vives|eres|elige|descubre')
const _FORMAL = _pal('usted')

/** cuántas marcas de cada registro hay en un texto (el «tu» posesivo NO cuenta: es igual en los tres) */
function marcasDeRegistro(texto) {
  const t = String(texto == null ? '' : texto)
  return { tuteo: (t.match(_TUTEO) || []).length, voseo: (t.match(_VOSEO) || []).length, formal: (t.match(_FORMAL) || []).length }
}

// ── lo que el manual DECLARA (texto normalizado sin tildes). Las negaciones («sin usted», «nunca uses vos») se resuelven antes.
const _DECLARA = {
  tuteo: [/\btutea(?:r|s|ndo)?\b/, /\btuteo\b/, /\b(?:nunca|jamas|no)\s+(?:uses?\s+|usar\s+|emplees?\s+)?vos\b/, /\b(?:habla|hablar|trato)\s+de tu\b/],
  voseo: [/\bvoseo\b/, /\bvosea(?:r|s)?\b/, /\b(?:usa|usar|emplea|emplear|habla|hablar)\s+(?:de\s+)?vos\b/, /\btrato de vos\b/],
  formal: [/\btrato de usted\b/, /\b(?:habla|hablar|siempre)\s+de usted\b/, /\bregistro formal\b/, /\busted(?:ea|ear|eo)\b/],
}
const _NEGACION_DE_USTED = /\b(?:sin|nunca|no)\s+(?:el\s+)?(?:uso\s+de\s+)?(?:trato\s+de\s+)?usted\b/g
function declaraRegistro(textos) {
  const hallados = {}
  for (const original of textos) {
    const t = _sinTildes(original).replace(_NEGACION_DE_USTED, ' ')
    for (const reg of Object.keys(_DECLARA)) for (const re of _DECLARA[reg]) { const m = t.match(re); if (m) (hallados[reg] = hallados[reg] || []).push('«' + m[0] + '»') }
  }
  const quienes = Object.keys(hallados)
  return quienes.length === 1 ? { registro: quienes[0], pruebas: hallados[quienes[0]] } : null // dos declaraciones contrarias ⇒ ninguna se elige
}

// ── los textos del manual: lo que DECLARA (campos de voz/tono/estilo) y todo lo que ESCRIBE (menos las listas de lo prohibido)
const _CLAVE_DE_VOZ = /voz|voice|tono|tone|estilo|style|personalidad|personality|registro|lenguaje|language|trato/i
const _CLAVE_A_SALTAR = /forbidden|prohib|evitar|avoid|competi|nunca_decir|banned/i
function _hojas(v, clave, out, saltar) {
  if (v == null) return
  if (typeof v === 'string') { out.push({ clave, texto: v }); return }
  if (Array.isArray(v)) { for (const x of v) _hojas(x, clave, out, saltar); return }
  if (typeof v === 'object') for (const k of Object.keys(v)) { if (saltar.test(k)) continue; _hojas(v[k], clave ? clave + '.' + k : k, out, saltar) }
}
function _textosDelManual(fila) {
  const out = []
  const f = fila && typeof fila === 'object' ? fila : {}
  for (const k of ['voice_description', 'tone_guidelines', 'writing_style', 'tagline', 'positioning', 'required_terminology']) _hojas(f[k], k, out, _CLAVE_A_SALTAR)
  if (typeof f.content_text === 'string') {
    try { const d = JSON.parse(f.content_text).brand_book_draft; if (d && typeof d === 'object') _hojas(d, '', out, _CLAVE_A_SALTAR) } catch (e) { /* ilegible: se ignora, no se inventa */ }
  }
  return out
}

/** el registro que fija el manual: declarado, inferido de lo escrito, o sin dato */
function registroDelManual(fila) {
  const hojas = _textosDelManual(fila)
  const dec = declaraRegistro(hojas.filter((h) => _CLAVE_DE_VOZ.test(h.clave || 'voz')).map((h) => h.texto))
  if (dec) return { registro: dec.registro, fuente: 'declarado_en_el_manual', pruebas: dec.pruebas.slice(0, 4) }
  const total = { tuteo: 0, voseo: 0, formal: 0 }, ejemplos = { tuteo: [], voseo: [], formal: [] }
  for (const h of hojas) {
    const m = marcasDeRegistro(h.texto)
    for (const r of Object.keys(total)) { total[r] += m[r]; if (m[r] && ejemplos[r].length < 4) ejemplos[r].push('«' + String(h.texto).replace(/\s+/g, ' ').slice(0, 60) + '»') }
  }
  const lados = Object.keys(total).filter((r) => total[r] > 0)
  if (lados.length === 1 && total[lados[0]] >= 2) return { registro: lados[0], fuente: 'inferido_de_los_textos_del_manual', pruebas: [total[lados[0]] + ' marcas de ' + lados[0] + ' y ninguna de otro registro'].concat(ejemplos[lados[0]]) }
  return { registro: 'sin_dato', fuente: 'sin_dato', pruebas: [] }
}

/** el registro final: el del manual si lo hay; si no, el del país de la ficha (declarado como omisión); si no, sin dato */
function registroFinal(delManual, pais) {
  const p = paisNormal(pais)
  const porPais = p && Object.prototype.hasOwnProperty.call(REGISTRO_POR_PAIS, p) ? REGISTRO_POR_PAIS[p] : null
  const hayManual = delManual && delManual.registro && delManual.registro !== 'sin_dato'
  // r63 · R-1: un registro solo INFERIDO (nadie lo declaró) no le gana a la regla del país: el manual puede venir contagiado por las instrucciones internas. Solo lo DECLARADO lo cambia.
  if (hayManual && delManual.fuente === 'inferido_de_los_textos_del_manual' && porPais && porPais !== delManual.registro) {
    return { registro: porPais, fuente: 'por_omision_del_pais_de_la_ficha', pruebas: ['país de la ficha: ' + String(pais).trim(), 'los textos del manual solo sugieren ' + delManual.registro + ' (' + (delManual.pruebas || [])[0] + ')'], aviso: 'el manual no lo declara: sus textos solo sugieren ' + delManual.registro + ' y la regla del país de la ficha es ' + porPais + ' · manda el país' }
  }
  if (hayManual) return Object.assign({}, delManual, { aviso: null })
  if (porPais) return { registro: porPais, fuente: 'por_omision_del_pais_de_la_ficha', pruebas: ['país de la ficha: ' + String(pais).trim()], aviso: 'el manual no fija el registro: se usa el del país de la ficha por omisión' }
  return { registro: 'sin_dato', fuente: 'sin_dato', pruebas: [], aviso: 'el manual no fija el registro y el país de la ficha no tiene uno por omisión' }
}

/** las líneas que entran al pedido del redactor */
function bloqueDeRegistro(r) {
  const cab = '══════ EL REGISTRO DE LA VOZ ══════'
  if (!r || r.registro === 'sin_dato') {
    return [cab,
      'El manual no fija el registro y no hay uno por omisión para este cliente: NO lo inventes.',
      'Escribe los textos publicables sin segunda persona marcada (ni vos ni tú ni usted): frases impersonales o en infinitivo.',
      'Declara este hueco en «que asumimos» del plan.', '']
  }
  const nombre = r.registro === 'tuteo' ? 'tuteo (segunda persona «tú»: tienes, quieres, elige)' : r.registro === 'voseo' ? 'voseo (segunda persona «vos»: tenés, querés, elegí)' : 'trato formal de usted'
  return [cab,
    'Registro: ' + nombre + '. Fuente: ' + r.fuente + (r.pruebas && r.pruebas.length ? ' · ' + r.pruebas.join(' · ') : '') + '.',
    'Todo texto pensado para publicarse o para que lo lea el cliente final (llamados a la acción, ejemplos de texto, titulares, guiones) va en ESE registro.',
    'Estas instrucciones pueden estar escritas en otro registro: no imites el registro de estas instrucciones.', '']
}

// r62 · el registro (tuteo / voseo / usted) que fija el manual · el redactor lo recibe en `manual.registro_del_manual`
const registro_del_manual = registroDelManual(m);
return [{ json: { client_id: cid, manual_id: m.id, manual_aprobado: true, registro_del_manual: registro_del_manual, identidad_del_manual: { primary_colors: m.primary_colors === undefined ? null : m.primary_colors, typography: m.typography === undefined ? null : m.typography } } }];

// ═══════════════════════════════════════════════════════════════════════════
// `elegir brazos` · decide QUÉ se le pide a quién para ESTE cliente.
// Contrato · §4.1 del diseño (2026-09-08). No inventa forma.
//
// 🔴 POR QUÉ EXISTE, medido y no supuesto (corridas 127323 y 127324 · 08-sep):
//    se le preguntó al redactor qué necesitaba para un gimnasio de barrio y para
//    una consultora B2B, y las dos listas NO coincidieron: 7 iguales, 2 distintas,
//    y distinto orden. Si fueran iguales, este nodo sobraría.
//
// ⚠️ LÍMITE DECLARADO POR QUIEN MIDIÓ: «son dos industrias, no un muestreo.
//    Alcanza para saber que el nodo hace falta; no alcanza para saber cuántas
//    ramas necesita.» ⇒ NÚCLEO FIJO + CONDICIONES. NO un árbol por industria.
//
// 🔴 `descartados` NO es decorativo: es la mitad del valor. Sin esa lista el
//    informe dice «no encontré X» y se lee como una falta. Con la lista dice
//    «no correspondía buscarlo».
//
// ═══════════════════════════════════════════════════════════════════════════
// 🔴 LOS PARÁMETROS LOS PONE ESTE NODO (2026-09-10 · Lenovo)
// ═══════════════════════════════════════════════════════════════════════════
// Un pedido sin parámetros está incompleto **del lado del que pide**. No los
// pone la ficha —sería volver a configurar por cliente— ni la puerta
// —interpretar es mentir—. Los pone el que decide QUÉ se pide, y los saca de la
// ficha, que ya lee.
//
// 🔴 Y la regla que va con eso: **un pedido que no se puede completar NO SALE.**
//    Se va a `descartados` diciendo QUÉ campo de la ficha falta. Antes salía
//    incompleto, el proveedor lo rechazaba, y el plan leía «no pudimos
//    verificarlo» — un hueco que en realidad era un dato que nadie cargó.
// ═══════════════════════════════════════════════════════════════════════════

const ficha = $input.first().json || {};
const cliente = ficha.cliente || ficha.client || ficha;

const cliente_id = cliente.id || cliente.client_id || cliente.cliente_id || null;
const nombre = (cliente.name || cliente.nombre || '').toString().trim();
const industria = (cliente.industry || cliente.industria || '').toString().trim();
const sitio = (cliente.website_url || cliente.sitio || cliente.website || null) || null;
const pais = (cliente.country || cliente.pais || '').toString().trim();
const cfg = (cliente.config && cliente.config.apify) || {};
const manijas = cfg.own_handles || cfg.own_social_handles || {};
const competidores = Array.isArray(cfg.competitor_list) ? cfg.competitor_list : [];

// 🔴 LOS COMPETIDORES SE LEEN DE SU TABLA, NO DE LA FICHA (2026-09-10 · decisión
// de Emilio). El proveedor exige `competitor_id` para no archivar la página del
// competidor como si fuera del cliente, y ese identificador **ya tiene casa**:
// `client_competitive_landscape`. Copiarlo a la ficha sería duplicar un dato que
// tiene dueño — y el duplicado se desactualiza.
// El nodo `Competidores del cliente` trae las filas; acá sólo se leen.
// 🔴 `null` = NO SE PUDO MIRAR · `[]` = se miró y no hay. No son lo mismo, y
// confundirlos es exactamente el defecto que esta pieza persigue.
let tabla = null;
try {
  const crudas = ($('Competidores del cliente').all() || []).map((i) => (i && i.json) || {});
  const esFila = (r) => r && typeof r === 'object' && typeof r.id === 'string';
  const esVacio = (r) => r && typeof r === 'object' && Object.keys(r).length === 0;
  // cualquier cosa que no sea una fila ni el hueco vacío es una lectura fallida
  // (un error del servicio, un permiso que falta) · NO es «no tiene competidores»
  const fallo = crudas.some((r) => !esFila(r) && !esVacio(r));
  tabla = fallo ? null : crudas.filter(esFila).filter((r) => (r.client_id ? r.client_id === cliente_id : true));
} catch (e) {
  // el nodo no corrió (o no existe) · tampoco es «no tiene competidores»
  tabla = null;
}

// ── LOS DOS EJES · son ejes, no rubros ─────────────────────────────────────
// La medición no separó «gimnasio» de «consultora»: separó DOS PROPIEDADES del
// negocio. Por eso acá hay dos preguntas, no una lista de industrias.
const txt = industria.toLowerCase();
const dice = (...ps) => ps.some((p) => txt.indexOf(p) >= 0);

// eje 1 · ¿le vende a EMPRESAS? · enciende SÓLO `competidores_precio` (la analítica propia ya no depende de esto · 30-sep)
const A_EMPRESAS = ['b2b', 'consultor', 'software', 'saas', 'agencia', 'industrial',
  'mayorista', 'distribuidor', 'fabrica', 'fábrica', 'manufactur', 'corporativ',
  'servicios profesionales', 'ingenier', 'legal', 'contab', 'logistic', 'logístic'];
// eje 2 · ¿atiende en un LOCAL? · es el que decide el orden de la ficha del mapa
const CON_LOCAL = ['restaurant', 'gimnasio', 'gym', 'cafe', 'café', 'bar', 'tienda',
  'hotel', 'hostal', 'peluquer', 'barber', 'clinica', 'clínica', 'spa', 'panader',
  'heladeria', 'heladería', 'local', 'comercio', 'retail', 'delivery', 'turismo'];

// 🔴 «unknown» NO es un rubro (medido 09-sep sobre las fichas reales: Peniche Surf
// Escape tiene literalmente `industry: "unknown"`). Leerlo como rubro válido haría
// decir «el rubro no lo requiere» cuando la verdad es «no sabemos qué rubro es» —
// que es exactamente el rótulo que miente que venimos persiguiendo.
const CENTINELAS_DE_VACIO = ['unknown', 'desconocido', 'n/a', 'na', 'null', 'sin definir', '-', '?'];
const sin_rubro = industria === '' || CENTINELAS_DE_VACIO.indexOf(txt) >= 0;
const a_empresas = !sin_rubro && dice.apply(null, A_EMPRESAS);
const con_local = !sin_rubro && dice.apply(null, CON_LOCAL);

// ═══════════════════════════════════════════════════════════════════════════
// LOS PARÁMETROS · sacados de la ficha, uno por uno, sin inventar ninguno
// ═══════════════════════════════════════════════════════════════════════════

// 🔴 un valor cargado a mano no siempre es una cuenta. Medido sobre las fichas
// reales: hay handles que dicen «Activo (sin handle público confirmado)». Eso no
// es una cuenta: es una nota. Se descarta como NO CARGADA, no se manda al
// proveedor a buscar una cuenta que se llama así.
const esUsable = (v) => {
  const s = String(v == null ? '' : v).trim();
  if (!s) return false;
  if (/\s/.test(s)) return false;          // una cuenta no tiene espacios
  if (/[()]/.test(s)) return false;        // ni paréntesis: eso es una aclaración
  return true;
};
const pelado = (v) => String(v).trim().replace(/^@+/, '').replace(/\/+$/, '');
const esUrl = (v) => /^https?:\/\//i.test(String(v).trim());
const url = (base, v) => (esUrl(v) ? String(v).trim() : base + pelado(v));

// el dominio para la analítica · la ficha NO tiene columna `domain` cargada
// (medido 10-sep: null en las 9 fichas) ⇒ sale del sitio, y se dice de dónde.
const dominioDelSitio = () => {
  if (!sitio) return null;
  try { return String(sitio).replace(/^https?:\/\//i, '').replace(/\/.*$/, '').trim() || null; }
  catch (e) { return null; }
};

// 🔴 el campo del sitio NO siempre tiene un sitio. Medido 10-sep: el cliente
// piloto tiene `website_url: "https://www.instagram.com/zeroriskgye/"`. Raspar
// eso y llamarlo «el sitio propio del cliente» sería un rótulo que miente — el
// plan leería una red social como si fuera la web del negocio.
const REDES_EN_EL_CAMPO_DEL_SITIO = ['instagram.com', 'facebook.com', 'fb.com',
  'tiktok.com', 'linkedin.com', 'youtube.com', 'youtu.be', 'x.com', 'twitter.com'];
const dom = (dominioDelSitio() || '').toLowerCase();
const sitio_es_una_red = REDES_EN_EL_CAMPO_DEL_SITIO.some((r) => dom === r || dom.endsWith('.' + r) || dom === 'www.' + r);

// las cinco redes canónicas · cada una con la forma que pide su raspador
const REDES = [
  { clave: 'instagram', funcion: 'instagram_scraper', arma: (h) => ({ directUrls: [url('https://www.instagram.com/', h)] }) },
  { clave: 'facebook', funcion: 'facebook_page_scraper', arma: (h) => ({ startUrls: [url('https://www.facebook.com/', h)] }) },
  { clave: 'tiktok', funcion: 'tiktok_profile_scraper', arma: (h) => ({ usernames: [pelado(h)] }) },
  { clave: 'linkedin', funcion: 'linkedin_company_scraper', arma: (h) => ({ companies: [pelado(h)] }) },
  { clave: 'youtube', funcion: 'youtube_channel_scraper', arma: (h) => ({ startUrls: [url('https://www.youtube.com/@', h)] }) },
];

// 🔴 devuelve los params, o el MOTIVO por el que el pedido no se puede completar.
// Nunca devuelve params a medias: o el pedido sale entero, o no sale.
const parametrosDe = (objetivo) => {
  if (objetivo === 'ficha_mapa') {
    if (!nombre) return { falta: 'la ficha no tiene el nombre del negocio · sin nombre no hay a quién buscar en el mapa' };
    // el país entra sólo si está · no se inventa una ciudad
    return { params: { searchStringsArray: [nombre + (pais ? ' ' + pais : '')] } };
  }

  if (objetivo === 'sitio_propio') {
    if (!sitio) return { falta: 'el cliente no tiene sitio cargado en su ficha · falta el dato, no el rubro' };
    if (sitio_es_una_red) {
      return { falta: 'el campo del sitio de la ficha tiene una RED SOCIAL (' + dom + '), no un sitio web · raspar eso y llamarlo «el sitio del cliente» sería un rótulo que miente · se arregla en la ficha' };
    }
    return { params: { url: sitio } };
  }

  if (objetivo === 'redes_sociales') {
    const por_funcion = {};
    const cargadas = [];
    const sin_cuenta = [];
    for (const r of REDES) {
      const h = manijas[r.clave];
      if (esUsable(h)) { por_funcion[r.funcion] = r.arma(h); cargadas.push(r.clave); }
      else { sin_cuenta.push(r.clave); }
    }
    if (cargadas.length === 0) {
      return { falta: 'la ficha no tiene ninguna cuenta de redes usable · falta el dato, no el rubro' };
    }
    // 🔴 las que no tienen cuenta VIAJAN DECLARADAS: sin esto, «no encontré nada
    // en TikTok» se leería como que el cliente no tiene TikTok, cuando lo que
    // pasa es que la ficha no lo dice.
    return { params: { por_funcion: por_funcion, redes_con_cuenta: cargadas, redes_sin_cuenta: sin_cuenta } };
  }

  if (objetivo === 'biblioteca_anuncios') {
    if (!nombre) return { falta: 'la ficha no tiene el nombre del negocio · sin nombre no hay a quién buscar en la biblioteca de anuncios' };
    return { params: { searchTerms: [nombre] } };
  }

  if (objetivo === 'tendencias_busqueda') {
    // se busca por el RUBRO (qué busca la gente de esa categoría) y, si no hay
    // rubro cargado, por el nombre del negocio. Se declara cuál de los dos se usó.
    const consulta = !sin_rubro ? industria : nombre;
    if (!consulta) return { falta: 'la ficha no dice ni el rubro ni el nombre · no hay con qué armar la búsqueda' };
    return { params: { queries: [consulta], de_donde: !sin_rubro ? 'el rubro de la ficha' : 'el nombre del negocio (la ficha no dice el rubro)' } };
  }

  if (objetivo === 'competidores_precio') {
    // 🔴 «no se pudo leer la tabla» NO es «no tiene competidores». Se distinguen.
    if (tabla === null) {
      return { falta: 'no se pudo leer la tabla de competidores · NO es que el cliente no tenga: es que no se pudo mirar' };
    }
    if (tabla.length === 0) {
      const enFicha = competidores.length;
      return { falta: enFicha > 0
        ? 'la tabla de competidores no tiene ninguno para este cliente, aunque la ficha lista ' + enFicha + ' · el dato vive en la tabla y ahí no está'
        : 'este cliente no tiene competidores cargados · falta el dato, no el rubro' };
    }
    // sin sitio no hay página que mirar · se dicen cuántos quedaron afuera y por qué
    const conSitio = tabla.filter((r) => String(r.competitor_website || '').trim());
    const sinSitio = tabla.filter((r) => !String(r.competitor_website || '').trim())
      .map((r) => r.competitor_name || r.id);
    if (conSitio.length === 0) {
      return { falta: 'los ' + tabla.length + ' competidores cargados no tienen sitio en la tabla · sin sitio no hay página que raspar' };
    }
    return { params: {
      // una corrida por competidor · cada una con SU sitio y SU identificador
      por_competidor: conSitio.map((r) => ({
        url: String(r.competitor_website).trim(),
        competitor_id: r.id,
        nombre: r.competitor_name || null,
      })),
      // 🔴 los que quedaron afuera VIAJAN DECLARADOS · sin esto, «encontré tres»
      // se leería como «tiene tres competidores»
      competidores_sin_sitio: sinSitio,
      de_donde: 'la tabla client_competitive_landscape · el identificador sale de ahí, no de la ficha',
      // y si la ficha dice otra cosa, se dice · no se elige una y se calla la otra
      desacuerdo_con_la_ficha: competidores.length !== tabla.length
        ? 'la ficha lista ' + competidores.length + ' y la tabla tiene ' + tabla.length + ' · manda la tabla, que es donde vive el identificador'
        : null,
    } };
  }

  if (objetivo === 'analitica_propia') {
    const d = dominioDelSitio();
    if (!d) return { falta: 'sin sitio en la ficha no hay dominio, y la analítica sólo se puede aproximar por dominio' };
    // 🔴 misma trampa que arriba: si el campo del sitio tiene una red social, el
    // dominio que sale de ahí NO es el del cliente. Pedir el tráfico de
    // instagram.com y llamarlo «la analítica del cliente» sería peor que no pedir
    // nada — la analítica ya sólo se puede aproximar por dominio.
    if (sitio_es_una_red) {
      return { falta: 'el campo del sitio de la ficha tiene una RED SOCIAL (' + dom + '), así que el dominio que sale de ahí no es el del cliente · y la analítica sólo se puede aproximar por dominio · se arregla en la ficha' };
    }
    return { params: { dominio: d, de_donde: 'el sitio de la ficha · la columna `domain` está vacía en todas las fichas' } };
  }

  if (objetivo === 'cerebro_cliente') {
    const q = [nombre, industria].filter(Boolean).join(' · ');
    if (!q) return { falta: 'la ficha no dice ni el nombre ni el rubro · no hay con qué preguntarle al cerebro' };
    return { params: { query: q } };
  }

  // `costo_pauta` lo atiende otro brazo y hoy no declara qué necesita.
  return { params: {} };
};

const pedidos = [];
const descartados = [];
const descartar = (objetivo, motivo) => descartados.push({ objetivo: objetivo, motivo: motivo });
// 🔴 acá se aplica la regla: el que no se puede completar NO SALE, y dice por qué
const pedir = (brazo, objetivo) => {
  const r = parametrosDe(objetivo);
  if (r.falta) { descartar(objetivo, r.falta); return; }
  pedidos.push({ brazo: brazo, objetivo: objetivo, orden: pedidos.length + 1, params: r.params });
};

// ── EL NÚCLEO FIJO · los SIETE, siempre ────────────────────────────────────
// El orden NO es decorativo: el mismo brazo cambia de prioridad según el rubro.
// Con local, la ficha del mapa va PRIMERA — de ahí salen las horas de mayor
// afluencia, que es como se encuentra la franja ociosa. Sin local, va después y
// sólo sirve de reputación.
if (con_local) {
  pedir('apify', 'ficha_mapa');
  pedir('apify', 'sitio_propio');
} else {
  pedir('apify', 'sitio_propio');
  pedir('apify', 'ficha_mapa');
}
pedir('apify', 'redes_sociales');
pedir('apify', 'biblioteca_anuncios');
pedir('apify', 'tendencias_busqueda');
pedir('plataforma', 'costo_pauta');
pedir('cerebro', 'cerebro_cliente');

// ── LA ANALÍTICA PROPIA ES NÚCLEO, NO CONDICIONAL (decisión de Emilio 2026-09-30) ─────────
// Somos una agencia agéntica para CUALQUIER cliente: el criterio correcto NO es a quién le vende, es si el sitio del cliente TIENE DATOS.
// Acá no se puede saber si los tiene (eso lo mira el brazo y contesta «trajo» o «se miró y no hay»): se pide siempre que haya un DOMINIO
// PROPIO. Si no lo hay (o el campo del sitio trae una red social), NO sale y se descarta diciendo QUÉ falta (lo dice `parametrosDe`).
// Medido 30-sep: naufrago.ec tiene 488 visitas en 90 días que este nodo nunca pidió porque «no le vende a empresas».
pedir('posthog', 'analitica_propia');

// ── UN CONDICIONAL · `competidores_precio` sigue siendo sólo de quien le vende a empresas (no se toca) ──────────────
if (sin_rubro) {
  // «no se pudo saber» NO es «no correspondía». Se dice cuál de los dos fue.
  descartar('competidores_precio', 'la ficha del cliente no dice a qué se dedica · no se pudo decidir');
} else if (a_empresas) {
  pedir('apify', 'competidores_precio');
} else {
  descartar('competidores_precio', 'el rubro no lo requiere · lo pidió sólo quien le vende a empresas');
}

// el orden se renumera al final · los que no salieron ya están en `descartados`
for (let i = 0; i < pedidos.length; i++) pedidos[i].orden = i + 1;
// 🔴 «NINGÚN BRAZO SALIÓ» ES ERROR, NO ÉXITO (2026-09-30 · decisión de Emilio · «un éxito mudo es justo la enfermedad que venimos cerrando»).
// Si no sale NINGÚN pedido para las tres ramas con brazo (apify · posthog · cerebro), la junta jamás dispara y la corrida terminaba «success» sin plan y sin error.
// Se detiene ACÁ, antes de gastar, y dice por qué se descartó cada cosa (lo que no se pudo pedir casi siempre es un dato que falta en la ficha).
const RAMAS_CON_BRAZO = ['apify', 'posthog', 'cerebro'];
if (!pedidos.some((p) => RAMAS_CON_BRAZO.indexOf(p.brazo) !== -1)) {
  throw new Error('PLANEACION_NINGUN_BRAZO_SALIO · ningún pedido salió hacia apify, posthog ni cerebro para el cliente ' + String(cliente_id) + ' · sin brazos no hay evidencia y el plan se escribiría a ciegas · la corrida SE DETIENE ANTES DE GASTAR · motivos: '
    + (descartados.length ? descartados.slice(0, 8).map((d) => d.objetivo + ' (' + d.motivo + ')').join(' · ') : 'ninguno declarado'));
}


// ── LOS TRES QUE NADIE PIDIÓ · se declaran, no se esconden ─────────────────
// Medido: ni el gimnasio ni la consultora los pidieron. No se sacan del catálogo
// (dos industrias no son un muestreo) pero se dice que no se buscaron.
descartar('velocidad_sitio', 'no lo pidió ninguno de los dos rubros medidos · queda fuera hasta que alguien lo pida');
descartar('alojamiento_capacidad', 'no lo pidió ninguno de los dos rubros medidos · queda fuera hasta que alguien lo pida');
descartar('manual_de_marca', 'no es objetivo de recolección · entra antes de los brazos');

return [{
  json: {
    cliente_id: cliente_id,
    industria: industria || null,
    sitio: sitio,
    pedidos: pedidos,
    descartados: descartados,
  },
}];

// [PLANEACIÓN] Derivador · §7-bis · la cadena del dinero · CÓDIGO, no un agente.
// 🔴 REGLA ÚNICA: lo que no se puede derivar devuelve no_derivable CON EL MOTIVO.
//    NUNCA un número. Un número sin insumo es el defecto más caro posible.
// Las TRES cuentas y nada más:
//   precio − costos variables        = contribución
//   contribución × % de la casa      = costo máximo por cliente
//   costo máximo × clientes objetivo = presupuesto
//   presupuesto ÷ contribución       = ventas de equilibrio
// El objetivo y el punto de partida NO son de este nodo: son del redactor.
const PCT_MIN = 0, PCT_MAX = 1;

const entrada = ($input.first() && $input.first().json) || {};
const eBase = entrada.derivador || entrada;
const e = Object.assign({}, eBase);

// 🔴 EL NÚMERO DE LA CASA · se LEE de `settings` EN CADA CORRIDA (E12-BIS · 12-sep).
// Antes nadie leía la fila: el puente lo declaraba por escrito y esta cuenta salía
// siempre `no_derivable`. Ahora entra por el mismo camino que el resto del paquete
// —`$('nodo')`, el patrón de la casa— y NO por un valor pegado acá.
//
// 🔴 LAS DOS REGLAS QUE NO SE NEGOCIAN:
//  ① si el pedido YA trae el porcentaje, NO se pisa. El de más abajo no manda.
//    (es el defecto que el cable de los brazos acaba de sacarse de encima)
//  ② si la fila no está, o no se pudo leer, o el valor no sirve, NO se rellena
//    con un número por defecto: sale HUECO DECLARADO, como salía hasta hoy.
//    Un `Code` no puede rellenar un hueco (§7-bis). Acá tampoco.
let fuentePct = 'el pedido ya lo traía';
if (e.porcentaje_de_la_casa === undefined || e.porcentaje_de_la_casa === null || e.porcentaje_de_la_casa === '') {
  fuentePct = 'no se pudo leer la fila `planeacion.porcentaje_de_la_casa` de `settings`';
  try {
    const fila = $('El número de la casa').first().json;
    const f = Array.isArray(fila) ? (fila[0] || {}) : (fila || {});
    const crudo = f.value !== undefined ? f.value : (f.valor !== undefined ? f.valor : undefined);
    // 🔴 la fila guarda TEXTO · medido: "0.70", no 0.7. El derivador RECHAZA texto a
    // propósito (§7-bis: adivinar el formato es lo que este nodo no hace). Así que se
    // convierte acá con una REGLA ESTRICTA y declarada: sólo dígitos y un punto.
    // "0,70", " 0.7 " o "mucho" NO se interpretan: salen hueco con el motivo.
    if (crudo === undefined || crudo === null || crudo === '') {
      fuentePct = 'la fila `planeacion.porcentaje_de_la_casa` no trajo valor';
    } else if (!/^[0-9]+(\.[0-9]+)?$/.test(String(crudo))) {
      fuentePct = 'el valor de la fila no es un número en punto decimal · llegó ' + JSON.stringify(crudo);
    } else {
      e.porcentaje_de_la_casa = Number(crudo);
      fuentePct = 'settings · planeacion.porcentaje_de_la_casa · leída en esta corrida · texto ' + JSON.stringify(crudo) + ' convertido con regla estricta';
    }
  } catch (x) {
    fuentePct = 'no se pudo leer el nodo `El número de la casa` · ' + x.message;
  }
}

const noDerivable = (motivo, falta) => ({ derivado: false, no_derivable: true, motivo: motivo, falta: falta });
// 🔴 no se convierte texto · '12,50' no es 12,5 acá: adivinar el formato es
// exactamente lo que este nodo existe para NO hacer.
const num = (v) => {
  if (v === null || v === undefined) return { ok: false, por: 'no llegó' };
  if (typeof v !== 'number') return { ok: false, por: 'llegó como ' + (typeof v) + ' (' + JSON.stringify(v) + ') y no como número' };
  if (!isFinite(v)) return { ok: false, por: 'llegó como un número no finito' };
  return { ok: true, n: v };
};
const cent = (n) => Math.round(n * 100) / 100;

// ① contribución
let contribucion;
{
  const p = num(e.precio), c = num(e.costos_variables);
  const falta = [], por = [];
  if (!p.ok) { falta.push('precio'); por.push('precio: ' + p.por); }
  if (!c.ok) { falta.push('costos_variables'); por.push('costos_variables: ' + c.por); }
  if (por.length) contribucion = noDerivable('no se puede calcular la contribución · ' + por.join(' · '), falta);
  else if (p.n < 0 || c.n < 0) contribucion = noDerivable('no se puede calcular la contribución · un precio o un costo negativo no es un dato, es un error de carga', [p.n < 0 ? 'precio' : 'costos_variables']);
  else { const v = cent(p.n - c.n); contribucion = { derivado: true, valor: v, formula: p.n + ' − ' + c.n + ' = ' + v, insumos: { precio: p.n, costos_variables: c.n } }; }
}

// ② costo máximo por cliente
let costo_maximo_por_cliente;
{
  const pct = num(e.porcentaje_de_la_casa);
  const falta = [], por = [];
  if (!contribucion.derivado) { falta.push.apply(falta, contribucion.falta); por.push('la contribución no se pudo derivar'); }
  if (!pct.ok) { falta.push('porcentaje_de_la_casa'); por.push('porcentaje_de_la_casa: ' + pct.por); }
  // 🔴 30 en vez de 0,30 multiplica el presupuesto por cien · se RECHAZA, no se interpreta
  else if (pct.n <= PCT_MIN || pct.n > PCT_MAX) { falta.push('porcentaje_de_la_casa'); por.push('porcentaje_de_la_casa: llegó ' + pct.n + ' · se espera una FRACCIÓN entre ' + PCT_MIN + ' y ' + PCT_MAX + ' (0,30 = 30 %)'); }
  if (por.length) costo_maximo_por_cliente = noDerivable('no se puede calcular el costo máximo por cliente · ' + por.join(' · '), falta);
  else if (contribucion.valor <= 0) costo_maximo_por_cliente = noDerivable('no se puede calcular el costo máximo por cliente · la contribución es ' + contribucion.valor + ': no hay margen del que pueda salir el costo de adquirir', ['precio', 'costos_variables']);
  else { const v = cent(contribucion.valor * pct.n); costo_maximo_por_cliente = { derivado: true, valor: v, formula: contribucion.valor + ' × ' + pct.n + ' = ' + v, insumos: { contribucion: contribucion.valor, porcentaje_de_la_casa: pct.n } }; }
}

// ③ presupuesto
let presupuesto;
{
  const o = num(e.clientes_objetivo);
  const falta = [], por = [];
  if (!costo_maximo_por_cliente.derivado) { falta.push.apply(falta, costo_maximo_por_cliente.falta); por.push('el costo máximo por cliente no se pudo derivar'); }
  if (!o.ok) { falta.push('clientes_objetivo'); por.push('clientes_objetivo: ' + o.por + ' · el objetivo lo fija el redactor, no se estima acá'); }
  else if (o.n <= 0 || Math.floor(o.n) !== o.n) { falta.push('clientes_objetivo'); por.push('clientes_objetivo: llegó ' + o.n + ' · se espera una cantidad entera mayor que cero'); }
  if (por.length) presupuesto = noDerivable('no se puede calcular el presupuesto · ' + por.join(' · '), falta);
  else { const v = cent(costo_maximo_por_cliente.valor * o.n); presupuesto = { derivado: true, valor: v, formula: costo_maximo_por_cliente.valor + ' × ' + o.n + ' = ' + v, insumos: { costo_maximo_por_cliente: costo_maximo_por_cliente.valor, clientes_objetivo: o.n } }; }
}

// ④ ventas de equilibrio · «¿cuánto vender para que se pague solo?»
let ventas_de_equilibrio;
{
  const falta = [], por = [];
  if (!presupuesto.derivado) { falta.push.apply(falta, presupuesto.falta); por.push('el presupuesto no se pudo derivar'); }
  if (!contribucion.derivado) { falta.push.apply(falta, contribucion.falta); por.push('la contribución no se pudo derivar'); }
  if (por.length) ventas_de_equilibrio = noDerivable('no se puede calcular las ventas de equilibrio · ' + por.join(' · '), falta);
  // 🔴 dividir por cero no da infinito acá: da un hueco con su motivo
  else if (contribucion.valor <= 0) ventas_de_equilibrio = noDerivable('no se puede calcular las ventas de equilibrio · la contribución es ' + contribucion.valor + ': sin margen positivo no hay cantidad de ventas que pague la inversión', ['precio', 'costos_variables']);
  else { const v = Math.ceil(presupuesto.valor / contribucion.valor); ventas_de_equilibrio = { derivado: true, valor: v, formula: presupuesto.valor + ' ÷ ' + contribucion.valor + ' = ' + v + ' (redondeado hacia arriba · ventas enteras)', insumos: { presupuesto: presupuesto.valor, contribucion: contribucion.valor } }; }
}

const pct = num(e.porcentaje_de_la_casa);
const pctOk = pct.ok && pct.n > PCT_MIN && pct.n <= PCT_MAX;

// pasa lo que venía + la cadena del dinero · el redactor recibe las dos cosas
return [{ json: Object.assign({}, entrada, { dinero: {
  contribucion: contribucion,
  costo_maximo_por_cliente: costo_maximo_por_cliente,
  presupuesto: presupuesto,
  ventas_de_equilibrio: ventas_de_equilibrio,
  hay_no_derivables: !(contribucion.derivado && costo_maximo_por_cliente.derivado && presupuesto.derivado && ventas_de_equilibrio.derivado),
  // 🔴 el valor que se USÓ y DE DÓNDE salió · lo lee el puente para el redactor
  porcentaje_de_la_casa_usado: pctOk ? pct.n : null,
  porcentaje_de_la_casa_de_donde: fuentePct,
  declaracion_del_porcentaje: pctOk ? ('se asumió ' + Math.round(pct.n * 100) + ' % de la contribución como techo para adquirir · la casa lo fija así, igual para todos los clientes') : null,
} }) }];

// ═══════════════════════════════════════════════════════════════════════════
// B4 · ARMAR EL PEDIDO DEL REDACTOR · contrato §4.3 de entrada.
//
// Convierte el paquete de recolección en el pedido que recibe el redactor.
// NO escribe el plan. NO decide nada del negocio. Sólo arma el pedido — pero
// arma el pedido de forma que INVENTAR sea más difícil que declarar.
//
// 🔴 LO QUE ESTE NODO EXISTE PARA IMPEDIR
//    El juez rechaza un plan si un número no dice de dónde salió («si no tiene
//    de dónde, el plan asumió» · medido 08-sep, corridas 127360/127361).
//    Y la recolección devuelve TRES estados que no se pueden aplanar:
//      trajo         hay dato
//      sin_dato      fui, miré y no hay      → es INFORMACIÓN
//      sin_respuesta no contestó / apagado   → es un HUECO
//    Si el pedido los mezcla, el plan escribe «el cliente no corre pauta»
//    cuando nadie preguntó. Por eso van SEPARADOS y con su motivo.
//
// 🔴 LOS DATOS QUE SÓLO TIENE EL DUEÑO · Emilio firmó la opción (b):
//    se ESTIMAN y se DECLARA que se estimaron.
//    ⚠️ EXCEPCIÓN, y es una sola: el % que la casa acepta gastar para adquirir
//    NO se estima. Es número de la casa. Si no está fijado, es un HUECO.
// ═══════════════════════════════════════════════════════════════════════════

// REGISTRO DEL CLIENTE · CC#2 · relevo 62 · el redactor del plan toma el registro (tuteo / voseo / usted) del MANUAL del cliente y no lo inventa.
// Texto plano que se PEGA TAL CUAL dentro de los nodos «① GUARDA» y «Redactor (B4)» de la planeación; la prueba `__tests__/planeacion-registro-del-cliente.test.ts` ejecuta ESTE MISMO texto.
// Agnóstico: ningún cliente, ciudad ni rubro. Los países de abajo son un DATO (se amplía sin tocar la lógica).
// Orden de autoridad: 1) lo que el manual DECLARA · 2) lo que el manual ESCRIBE (≥ 2 marcas de un lado y 0 del otro) · 3) el país de la ficha, por omisión y DECLARADO como omisión · 4) sin dato (se dice).

// DATO · registro por omisión por país (claves en minúsculas y sin tildes). Un país que no está aquí NO tiene registro por omisión.
// ═══ PAÍS → TRATO · ÚNICA FUENTE (ronda 67 · CC#1 · 2026-10-11) ═══
// El trato habitual del país SÓLO cuando nadie lo dijo (baja confianza · se declara) · sin país conocido no hay default. UNA sola tabla: la planeación, el alta, el brief, la pieza y la copia por filas
// llevan ESTE MISMO bloque (lo pega el constructor y una prueba exige que sea idéntico). Las claves son el nombre en minúsculas y sin tildes; los códigos de dos letras y los alias entran por `paisNormal`.
// Es un DATO (se amplía sin tocar la lógica): la UNIÓN verificada de las tres tablas que se habían apartado (el detector: 12 países; el registro de la planeación: 15, con Colombia, Cuba, Puerto Rico y República Dominicana, sin Costa Rica).
var POR_PAIS = { argentina: 'vos', uruguay: 'vos', paraguay: 'vos', ecuador: 'tu', mexico: 'tu', peru: 'tu', chile: 'tu', espana: 'tu', bolivia: 'tu', venezuela: 'tu', panama: 'tu', colombia: 'tu', cuba: 'tu', 'puerto rico': 'tu', 'republica dominicana': 'tu', 'costa rica': 'usted' }
var CODIGO_PAIS = { ar: 'argentina', uy: 'uruguay', py: 'paraguay', ec: 'ecuador', mx: 'mexico', pe: 'peru', cl: 'chile', es: 'espana', bo: 'bolivia', ve: 'venezuela', pa: 'panama', co: 'colombia', cu: 'cuba', pr: 'puerto rico', do: 'republica dominicana', cr: 'costa rica' }
var ALIAS_PAIS = { dominicana: 'republica dominicana', 'rep dominicana': 'republica dominicana', spain: 'espana' }
/** el país como lo escribe una ficha («Ecuador.», «EC», «República Dominicana», «Rep. Dominicana») → la clave de la tabla; texto sin reconocer vuelve normalizado (nunca se adivina) */
function paisNormal(s) {
  var t = String(s === undefined || s === null ? '' : s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim()
