// nadie le preguntó. Lo que no se pidió ya está declarado en 'descartados' (§4.1).

// 🔴 el pasamanos de un nodo APAGADO se deja pasar INTACTO: lo reconoce y lo
// declara la junta (CC#1). Reescribirlo la cegaría.
const esPasamanos = (j) => !!j && typeof j === 'object' && !Array.isArray(j) &&
  ESTADOS.indexOf(j.estado) === -1 && (Array.isArray(j.pedidos) || Array.isArray(j.descartados));

const salida = [];
const abrirPorObjetivo = (base) => {
  for (const objetivo of objetivos) salida.push({ json: Object.assign({}, base, { brazo: BRAZO, objetivo: objetivo }) });
};

for (const it of $input.all()) {
  const j = it.json || {};
  if (esPasamanos(j)) { salida.push({ json: j }); continue; }
  // 🔴 si no hay objetivos, no hay material · también en el camino de ÉXITO.
  // Con las puertas en 404 todo caía por el camino del fallo y el agujero no se
  // veía; publicadas, la rama sin pedidos recibe un «pedidos vino vacío» bien
  // formado y se firmaba con un objetivo inventado (corrida 130108: 7 de 7
  // objetivos y 3 brazos, cuando eran 6 y 2). Lo encontró CC#1.
  if (!objetivos.length) continue;
  if (Object.keys(j).length === 0) {
    abrirPorObjetivo({ error: 'la rama contestó con un item vacío · no alcanza para afirmar que se miró' });
    continue;
  }
  if (j.error !== undefined && j.error !== null) { abrirPorObjetivo({ error: j.error }); continue; }
  const cuerpo = Array.isArray(j.respuestas) ? j.respuestas : [j];
  for (const r of cuerpo) {
    const p = r || {};
    salida.push({ json: Object.assign({}, p, {
      brazo: (typeof p.brazo === 'string' && p.brazo) ? p.brazo : BRAZO,
      objetivo: (typeof p.objetivo === 'string' && p.objetivo) ? p.objetivo
        : (objetivos.length === 1 ? objetivos[0] : '(la puerta no dijo de qué objetivo hablaba)'),
    }) });
  }
}

if (!salida.length) abrirPorObjetivo({ error: 'la rama no produjo ningún item' });
return salida;

// firma de la rama · posthog · §4.2 · CC#2 2026-09-10
// 🔴 La identidad del brazo tiene que venir del LUGAR por donde pasa, nunca del
// contenido que se esperaba: cuando el paso de red falla, n8n entrega
// { error: … } SIN el cuerpo que se mandó, y la junta leía 'desconocido'.
