};

const pedidos = [];
const descartados = [];
const descartar = (objetivo, motivo) => descartados.push({ objetivo: objetivo, motivo: motivo });
// 🔴 acá se aplica la regla: el que no se puede completar NO SALE, y dice por qué
const pedir = (brazo, objetivo) => {
