// 🔴 UNA CORRIDA SIN PDF NO PUEDE SALIR EXITOSA (2026-09-12 · CC#3)
//
// Ahora hay TRES cosas que pueden faltar, y se dicen por separado:
//   la vuelta del redactor · el guardado del plan · el PDF
// El guardado va ANTES de Drive a propósito: si Drive falla, el plan NO se pierde
// (medido el 12-sep: un plan de 22.060 caracteres se perdió entero porque nadie
// lo había guardado · el registro de invocaciones sólo conserva 2.000).
const v = $('¿Llegó la vuelta?').first().json;
const texto = String(v.texto || '');
const hayPlan = texto.trim().length > 0;

let guardado = false, guardado_id = null;
try {
  const g = $('Guardar el plan').first().json;
  const gb = (g && g.body) ? g.body : g;
  const fila = Array.isArray(gb) ? gb[0] : gb;
  guardado = !!(fila && fila.id);
  guardado_id = fila && fila.id || null;
} catch (x) { guardado = false; }

let rec = null;
try { const d = $('Plan → Drive (PDF)').first().json; rec = (d && d.body) ? d.body : d; } catch (x) { rec = null; }
const hayPdf = !!(rec && rec.ok === true && rec.file_id);

const problemas = [];
if (!hayPlan) problemas.push(v.motivo || 'el redactor no devolvió texto');
if (hayPlan && !guardado) problemas.push('el plan NO quedó guardado · si Drive falla se pierde');
if (!hayPdf) problemas.push(hayPlan
  ? ('Drive no devolvió un archivo (' + String((rec && rec.motivo) || 'sin motivo') + ')')
  : 'no se llamó a Drive porque no había plan que escribir');

return [{ json: {
  ok: problemas.length === 0,
  llego_la_vuelta: v.llego_la_vuelta === true,
  hay_plan: hayPlan,
  caracteres_del_plan: texto.length,
  plan_guardado: guardado,
  plan_guardado_id: guardado_id,
  hay_pdf: hayPdf,
  file_id: rec && rec.file_id || null,
  url: rec && rec.url || null,
  carpeta: rec && rec.folder_id || null,
  problemas: problemas,
  client_id: v.client_id,
  client_name: v.client_name,
} }];

// 🔴 EL AVISO DICE QUÉ HACER · no sólo que falló.
const r = $input.first().json;
const pasos = [];
if (!r.llego_la_vuelta) {
  pasos.push('1) la vuelta NO llegó · el plan PUEDE estar escrito: mira agent_invocations por client_id y fíjate response_length');
  pasos.push('2) si response_length es grande, el texto completo NO está en la base (guarda 2.000) · búscalo en Braintrust por session_id');
  pasos.push('3) comprueba el saldo del proveedor ANTES de reintentar · y NO repagues el raspado: reusa el pedido que armó «Redactor (B4)»');
} else if (!r.plan_guardado) {
  pasos.push('1) el plan llegó (' + r.caracteres_del_plan + ' caracteres) pero NO se guardó · revisa los permisos de client_historical_outputs');
  pasos.push('2) el texto está en esta corrida de n8n · copialo de «¿Llegó la vuelta?» antes de que caduque el historial (~4 h)');
} else {
  pasos.push('1) el plan está guardado (' + String(r.plan_guardado_id).slice(0, 8) + '…) · NO hay que volver a pagar al redactor');
  pasos.push('2) lo que falló es Drive · mira la credencial de Google en n8n · caduca cada 7 días si la app OAuth no está publicada');
  pasos.push('3) reintenta sólo Drive: POST a /webhook/zero-risk/texto-a-drive con client_id, client_name, nombre y el texto guardado');
}
return [{ json: {
  texto: ':rotating_light: *Plan sin PDF* — la corrida de planeación terminó sin documento en Drive.\n' +
    '• cliente: `' + String(r.client_name || r.client_id || '?') + '`\n' +
    '• qué falló: ' + r.problemas.join(' · ') + '\n' +
    '• plan escrito: ' + (r.hay_plan ? (r.caracteres_del_plan + ' caracteres') : 'NO') +
    ' · guardado: ' + (r.plan_guardado ? 'SÍ' : 'NO') + '\n' +
    '*Qué hacer:*\n' + pasos.map((p) => '  ' + p).join('\n'),
} }];

