try { registroDelPlan = $('Redactor (B4)').first().json.registro_usado.registro; } catch (x) { registroDelPlan = null; }
// r73 · la frase de calentamiento del modelo («Voy a escribir el plan…» + ---) NO es parte del documento: por código, antes de revisar el registro
const sinCalentamiento = llego ? quitarCalentamiento(textoDelRedactor) : { texto: textoDelRedactor, quitado: '' };
const textoBase = sinCalentamiento.texto.trim() ? sinCalentamiento.texto : textoDelRedactor;
const revisionDeRegistro = llego ? corregirRegistroDelPlan(textoBase, registroDelPlan) : null;
const textoRevisado = revisionDeRegistro ? revisionDeRegistro.texto : textoDelRedactor;
const bloqueRevision = revisionDeRegistro ? bloqueDeRevisionDeRegistro(revisionDeRegistro, registroDelPlan) : '';
// r73 · chequeo del plan por código (P1–P6): marca lo que no debe llegar al cliente; no corrige, avisa
let contextoChequeo = null;
try { contextoChequeo = $('Redactor (B4)').first().json.contexto_chequeo; } catch (x) { contextoChequeo = null; }
const chequeoDelPlan = llego ? revisarPlan(textoRevisado, contextoChequeo) : null;
const bloqueChequeo = chequeoDelPlan ? bloqueDeRevisionDelPlan(chequeoDelPlan) : '';
// r80 · si el chequeo marca, el plan queda «con pendientes» (no listo, no para el cliente) y alguien se entera: la línea de pendientes va a la bandeja
const pendientes = chequeoDelPlan ? pendientesDelPlan(chequeoDelPlan) : null;
const estadoDelPlan = !llego ? null : (pendientes ? 'con_pendientes' : 'sin_marcas');
const texto = llego ? textoRevisado.replace(/\s+$/, '') + '\n' : textoDelRedactor;
// r78 · lo interno NO va al plan del cliente: va al registro interno (se guarda con el plan y queda en la salida del nodo)
const registroInterno = llego ? { revision_del_registro: bloqueRevision || null, aviso_del_chequeo: bloqueChequeo || null, no_se_busco_del_sistema: bloqueDescartados || null } : null;

let cid = null, cnom = null;
try { cid = $('Redactor (B4)').first().json.cliente_id; } catch (x) { /* */ }
try { cnom = $('Ficha del cliente').first().json.name; } catch (x) { /* */ }

return [{ json: {
  llego_la_vuelta: llego,
  texto: texto,
  caracteres: texto.length,
  registro_revisado: revisionDeRegistro ? { registro: registroDelPlan, corregidas: revisionDeRegistro.corregidas.length, formas_corregidas: revisionDeRegistro.corregidas.map((x) => x.antes + ' → ' + x.despues).slice(0, 40), restantes: revisionDeRegistro.restantes } : null,
  calentamiento_quitado: sinCalentamiento.quitado || null,
  chequeo_del_plan: chequeoDelPlan,
  registro_interno: registroInterno,
  estado_del_plan: estadoDelPlan,
  con_pendientes: estadoDelPlan === 'con_pendientes',
  pendientes: pendientes,
  descartados_declarados: llego && Array.isArray(descartados) ? descartados.length : null,
  no_se_busco_interno: llego && Array.isArray(descartados) ? descartados : null,
  client_id: cid,
  client_name: cnom,
  motivo: llego ? null
    : 'la vuelta del redactor NO llegó · se agotó la espera · el plan puede haberse escrito igual y estar en el corredor · NO se da por exitosa',
} }];

// [PLANEACIÓN] ② GUARDA · sin referencia del producto se DETIENE · E16 · 2026-09-12
//
// 🔴 POR QUÉ ES UN NODO APARTE Y NO UNA LÍNEA ADENTRO DEL REDACTOR:
// el nodo `Redactor (B4)` tiene `onError: continueRegularOutput` — se traga sus
// propios errores. Un `throw` adentro NO detiene nada: la corrida seguiría hasta
// `Pedir el plan al redactor` y pagaría igual. Lo probé antes de publicarlo.
// Este nodo NO lleva `onError`: el que falla acá, detiene. Mismo patrón que la
// guarda del manual de marca, que es la otra cosa sin la cual no hay plan.
//
// ⚠️ NO CONTRADICE LA REGLA 0 DE EMILIO: un dato del NEGOCIO que falta (precio,
// costos, presupuesto) NO bloquea · se declara el hueco y el plan sale igual.
// Esto es el CONTRATO del producto: sin las ocho secciones no hay plan, hay
// redacción libre. Material faltante ⇒ se declara. Escritura rota ⇒ se detiene.
const REFERENCIA_MINIMA = 2000;
const entrada = ($input.first() && $input.first().json) || {};
const ref = String(entrada.referencia || '').trim();
const loQueDiceElPuente = String((entrada.puente_declara || {}).referencia || 'el puente no declaró nada');
if (ref.length < REFERENCIA_MINIMA) {
  throw new Error('PLANEACION_REFERENCIA_VACIA · el documento de referencia del producto llegó con '
    + ref.length + ' caracteres (mínimo ' + REFERENCIA_MINIMA + ') · sin las ocho secciones el plan no'
    + ' tiene estructura pedida y el redactor escribiría a criterio propio · la corrida SE DETIENE'
    + ' antes de invocar y NO se gasta · lo que dice el puente: ' + loQueDiceElPuente);
}
// 🟢 pasa tal cual · una guarda no transforma lo que deja pasar
return $input.all();

// Si la puerta no acepto el sobre, NO se calla. Mismo patron que el resto de la casa (E101):
// una nota perdida se DECLARA, no se traga. No corrige nada.
const r = $input.first().json || {};
const cuerpo = r.body || r;
const ok = !!cuerpo && (cuerpo.ok === true || cuerpo.kind === 'accepted' || cuerpo.kind === 'duplicate');
if (!ok) {
  return [{ json: { _nota_perdida: true, motivo: 'SOBRE_DEL_BRIEF_NO_ACEPTADO',
    detalle: (cuerpo && (cuerpo.detail || cuerpo.code)) || 'sin detalle',
    flujo: 'X9F0zp6LQ2xGEYVS', nodo: "BRIEF · sobre · pedir el parte a la sala (E-brief · CC#2)" } }];
}
return [{ json: { _nota_perdida: false, sobre: cuerpo.kind || 'accepted', event_id: cuerpo.event_id || null } }];

// ⑤ SECO · LO QUE SE HABRÍA ESCRITO · CC#1 · 2026-09-30. En modo seco NADA se escribe, ni se sube, ni se avisa: ni la tabla, ni Drive, ni la sala, ni el aviso, ni el parte.
// Llega hasta acá con el MISMO camino que el real (ficha · manual · brazos · junta · derivador · pedido al redactor · espera · vuelta) y aquí sólo se DECLARA lo que habría pasado.
const v = $input.first().json || {}
const sobre = $('Webhook · planeacion').first().json.body || {}
if (!v.llego_la_vuelta) {
  throw new Error('PLANEACION_SECO_SIN_VUELTA · en el ensayo la vuelta del redactor NO llegó (' + String(v.motivo || 'sin motivo') + ') · en modo real esto habría terminado en aviso, no en plan')
}
const texto = String(v.texto || '')
return [{
  json: {
    seco: true,
    escrituras_reales: 0,
    no_se_escribio_en: ['client_historical_outputs (Guardar el plan)', 'Drive (texto-a-drive)', 'la sala (SALA_CALLBACK_URL · cable de vuelta)', 'el parte del brief (sobre plan-listo)', '#alertas (avisos)'],
    dry_run_enviado_al_nodo_que_paga: true,
    client_id: v.client_id || sobre.client_id || null,
    la_vuelta_del_redactor: { llego: !!v.llego_la_vuelta, caracteres: v.caracteres, bloque_de_lo_que_no_se_busco: texto.indexOf('## Lo que NO se buscó y por qué') !== -1, descartados_declarados: v.descartados_declarados === undefined ? null : v.descartados_declarados },
    habria_guardado: { tabla: 'client_historical_outputs', output_type: 'campaign_plan_90d', status: 'draft', largo_del_plan: texto.length },
    habria_subido_a_drive: { nombre_de_cliente: v.client_name || null, largo_del_texto: texto.length },
    habria_avisado_a_la_sala: { event_type: 'run_completed', worker_name: 'planeacion' },
    forzar_recibido: sobre.forzar === true,
  },
}]

// ⓪ LA LLAVE · CC#2 · relevo 15 (2026-10-08) · mismo patrón que `zero-risk/brief` y `zero-risk/pieza` (lección E67).
// Este flujo GASTA (modelo, Apify, imagen o video) o PUBLICA hacia afuera (redes, correo). Por eso exige la llave de despacho del motor en la cabecera
// `x-sala-dispatch-key` (la misma `SALA_DISPATCH_KEY` del entorno de n8n; no se copia a ningún otro sitio) y, si falta, se DETIENE antes de tocar nada.
// Falla CERRADO: sin la llave en el entorno, el flujo queda cerrado. Los disparos con horario (cron) y las llamadas internas entre flujos no pasan por aquí.
const w = $input.first().json || {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}
const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) {
  throw new Error('FLUJO_CERRADO · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) en su entorno · este flujo gasta o publica y queda cerrado hasta que exista · E67.')
}
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) {
  throw new Error('FLUJO_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · este flujo gasta o publica y solo lo despierta la sala · E67.')
}
return $input.all()

// r78 · lo que dijo el dueño, entregado por la función compartida (no por casualidad del cerebro). Si la lectura FALLA, la corrida SE DETIENE: un fallo no se lee como «no dijo nada».
const base = $('② GUARDA · sin referencia del producto se DETIENE').first().json;
const d = $input.first().json || {};
if (d.ok !== true) {
  throw new Error('PLANEACION_SIN_LECTURA_DE_LO_DEL_DUENO · no se pudo leer lo que el dueño declaró (' + [d.error, d.detail].filter(Boolean).join(' · ') + ') · la corrida SE DETIENE antes de invocar y NO se gasta');
}
return [{ json: Object.assign({}, base, { hechos_del_dueno: Array.isArray(d.hechos) ? d.hechos : [] }), pairedItem: { item: 0 } }];

// r80 · el plan con marcas NO queda «listo» en silencio: una línea para quien administra la agencia, en la bandeja (qué falta). Sin marcas: no sale ningún elemento y la rama termina aquí.
const v = $('¿Llegó la vuelta?').first().json;
if (!v.con_pendientes) return [];
let planId = null;
try { const g = $('Guardar el plan').first().json; const gb = (g && g.body) ? g.body : g; const fila = Array.isArray(gb) ? gb[0] : gb; planId = (fila && fila.id) || null; } catch (x) { planId = null; }
const quien = String(v.client_name || 'el cliente');
const linea = ('Plan de 90 días de ' + quien + ' con pendientes: ' + String(v.pendientes || 'el chequeo marcó el plan')).slice(0, 480);
const cuerpo = {
  type: 'plan_con_pendientes',
  title: linea,
  client_id: v.client_id || null,
  priority: 'high',
  agent_name: 'planeacion',
  risk_type: 'strategic_decision',
  output_preview: linea,
  payload: { plan_id: planId, estado_del_plan: v.estado_del_plan, marcas: (v.chequeo_del_plan && v.chequeo_del_plan.marcas) || [], para_el_cliente: false },
};
if (planId && v.client_id) cuerpo.output_id = planId;
return [{ json: { cuerpo } }];

// r80 · si la bandeja NO recibió el aviso, la corrida sale en ERROR a la vista (el plan ya está guardado y entregado a la sala: esto va al final a propósito)
const r = $input.first().json || {};
const hay = r.id || (r.item && r.item.id) || (r.ok === true) || (r.data && r.data.id);
if (!hay) throw new Error('PLAN_CON_PENDIENTES_SIN_AVISO · la bandeja no recibió el aviso (' + JSON.stringify(r).slice(0, 300) + ') · el plan está guardado como «con pendientes»: avisar a mano');
return [{ json: { aviso_en_bandeja: true, respuesta: r } }];
